/*
	 * Verify queue is declared if not present and not declared if it is already present.
	 */
@Test
public void channelDeclarationTests() {
    RabbitAdmin admin = new RabbitAdmin(this.connectionFactory);
    admin.deleteQueue("implicit");
    SimpleMessageListenerContainer container = new SimpleMessageListenerContainer(this.connectionFactory);
    container.setAutoStartup(false);
    AmqpTemplate amqpTemplate = mock(AmqpTemplate.class);
    PointToPointSubscribableAmqpChannel channel = new PointToPointSubscribableAmqpChannel("implicit", container, amqpTemplate);
    channel.setBeanFactory(mock(BeanFactory.class));
    channel.afterPropertiesSet();
    channel.onCreate(null);
    assertThat(admin.getQueueProperties("implicit")).isNotNull();
    admin.deleteQueue("explicit");
    channel.setQueueName("explicit");
    channel.afterPropertiesSet();
    channel.onCreate(null);
    assertThat(admin.getQueueProperties("explicit")).isNotNull();
    admin.deleteQueue("explicit");
    // verify no declaration if exists with non-standard props
    admin.declareQueue(new Queue("explicit", false));
    channel.afterPropertiesSet();
    channel.onCreate(null);
    assertThat(admin.getQueueProperties("explicit")).isNotNull();
    admin.deleteQueue("explicit");
}

@Test
public void messageConversionTests() {
    RabbitTemplate amqpTemplate = new RabbitTemplate(this.connectionFactory);
    MessageConverter messageConverter = mock(MessageConverter.class);
    amqpTemplate.setMessageConverter(messageConverter);
    PointToPointSubscribableAmqpChannel channel = new PointToPointSubscribableAmqpChannel("testConvertFail", new SimpleMessageListenerContainer(this.connectionFactory), amqpTemplate);
    channel.setBeanFactory(mock());
    channel.afterPropertiesSet();
    MessageListener listener = TestUtils.getPropertyValue(channel, "container.messageListener", MessageListener.class);
    willThrow(new MessageConversionException("foo", new IllegalStateException("bar"))).given(messageConverter).fromMessage(any(org.springframework.amqp.core.Message.class));
    assertThatExceptionOfType(MessageConversionException.class).isThrownBy(() -> listener.onMessage(mock(org.springframework.amqp.core.Message.class))).withCauseInstanceOf(IllegalStateException.class);
}

