@Test
@SuppressWarnings("unchecked")
public void errorFlowAndRetries() throws Exception {
    delayHandler.setDefaultDelay(10);
    delayHandler.setRetryDelay(15);
    startDelayerHandler();
    Message<?> message = MessageBuilder.withPayload("test").setHeader("foo", new AtomicInteger()).build();
    final CountDownLatch latch = new CountDownLatch(1);
    final AtomicInteger count = new AtomicInteger();
    delayHandler.setDelayedMessageErrorChannel((m, t) -> {
        count.incrementAndGet();
        int deliveries = StaticMessageHeaderAccessor.getDeliveryAttempt(m).get();
        ((MessagingException) m.getPayload()).getFailedMessage().getHeaders().get("foo", AtomicInteger.class).incrementAndGet();
        if (deliveries < 3) {
            throw new RuntimeException("fail");
        } else if (deliveries == 3) {
            return false;
        } else {
            latch.countDown();
            return true;
        }
    });
    delayHandler.setOutputChannel((m, t) -> {
        throw new MessagingException(m);
    });
    input.send(message);
    assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
    Thread.sleep(50);
    assertThat(count.get()).isEqualTo(4);
    assertThat(TestUtils.getPropertyValue(this.delayHandler, "deliveries", Map.class)).hasSize(0);
}

