@Test
public void testUseSpelInvoker() throws Exception {
    UseSpelInvokerBean bean = new UseSpelInvokerBean();
    MessagingMethodInvokerHelper helper = new MessagingMethodInvokerHelper(bean, UseSpelInvokerBean.class.getDeclaredMethod("foo", String.class), false);
    helper.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    Message<?> message = new GenericMessage<>("Test");
    helper.process(message);
    assertThat(TestUtils.getPropertyValue(helper, "handlerMethod.expression.configuration.compilerMode")).isEqualTo(SpelCompilerMode.OFF);
    helper = new MessagingMethodInvokerHelper(bean, UseSpelInvokerBean.class.getDeclaredMethod("bar", String.class), false);
    helper.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    helper.process(message);
    assertThat(TestUtils.getPropertyValue(helper, "handlerMethod.expression.configuration.compilerMode")).isEqualTo(SpelCompilerMode.IMMEDIATE);
    helper = new MessagingMethodInvokerHelper(bean, UseSpelInvokerBean.class.getDeclaredMethod("baz", String.class), false);
    helper.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    helper.process(message);
    assertThat(TestUtils.getPropertyValue(helper, "handlerMethod.expression.configuration.compilerMode")).isEqualTo(SpelCompilerMode.MIXED);
    helper = new MessagingMethodInvokerHelper(bean, UseSpelInvokerBean.class.getDeclaredMethod("qux", String.class), false);
    helper.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    helper.process(message);
    assertThat(TestUtils.getPropertyValue(helper, "handlerMethod.expression.configuration.compilerMode")).isEqualTo(SpelCompilerMode.OFF);
    helper = new MessagingMethodInvokerHelper(bean, UseSpelInvokerBean.class.getDeclaredMethod("fiz", String.class), false);
    helper.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    try {
        helper.process(message);
    } catch (IllegalArgumentException e) {
        assertThat(e.getMessage()).isEqualTo("No enum constant org.springframework.expression.spel.SpelCompilerMode.JUNK");
    }
    helper = new MessagingMethodInvokerHelper(bean, UseSpelInvokerBean.class.getDeclaredMethod("buz", String.class), false);
    ConfigurableListableBeanFactory bf = mock();
    willAnswer(returnsFirstArg()).given(bf).resolveEmbeddedValue(anyString());
    when(bf.containsBean(eq(IntegrationContextUtils.INTEGRATION_EVALUATION_CONTEXT_BEAN_NAME))).thenReturn(true);
    StandardEvaluationContext evaluationContext = new StandardEvaluationContext();
    evaluationContext.addPropertyAccessor(new MapAccessor());
    when(bf.getBean(eq(IntegrationContextUtils.INTEGRATION_EVALUATION_CONTEXT_BEAN_NAME), any(Class.class))).thenReturn(evaluationContext);
    helper.setBeanFactory(bf);
    try {
        helper.process(message);
    } catch (IllegalArgumentException e) {
        assertThat(e.getMessage()).isEqualTo("UseSpelInvoker.compilerMode: Object of class [java.lang.Object] " + "must be an instance of class java.lang.String");
