    Message<?> received = requestChannel.receive(10000);
    assertThat(received).isNotNull();
    assertThat(received.getPayload()).isInstanceOf(byte[].class);
    assertThat(new String((byte[]) received.getPayload())).isEqualTo(testData);
}

