private void testCloseStream(AbstractServerConnectionFactory scf, Function<Integer, AbstractClientConnectionFactory> ccf) throws InterruptedException, IOException {
    scf.setApplicationEventPublisher(TEST_INTEGRATION_CONTEXT);
    scf.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    scf.setSingleUse(true);
    scf.setDeserializer(new ByteArrayRawSerializer());
    scf.afterPropertiesSet();
    TcpInboundGateway gateway = new TcpInboundGateway();
    gateway.setConnectionFactory(scf);
    BeanFactory bf = mock(ConfigurableBeanFactory.class);
    gateway.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    gateway.start();
    TestingUtilities.waitListening(scf, 20000L);
    int port = scf.getPort();
    final DirectChannel channel = new DirectChannel();
    gateway.setRequestChannel(channel);
    BridgeHandler bridge = new BridgeHandler();
    bridge.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    bridge.afterPropertiesSet();
    ConsumerEndpointFactoryBean consumer = new ConsumerEndpointFactoryBean();
    consumer.setInputChannel(channel);
    consumer.setBeanFactory(bf);
    consumer.setHandler(bridge);
    consumer.afterPropertiesSet();
    consumer.start();
    AbstractClientConnectionFactory client = ccf.apply(port);
    CountDownLatch latch = new CountDownLatch(1);
    client.registerListener(message -> latch.countDown());
    client.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    client.afterPropertiesSet();
    client.start();
    TcpConnectionSupport connection = client.getConnection();
    connection.send(new GenericMessage<>("foo"));
    // signal EOF to server
    connection.shutdownOutput();
    assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
    gateway.stop();
    client.stop();
}

