public void testInt3088MPutNotRecursive() throws Exception {
    resetSessionCache();
    this.config.events.clear();
    this.config.latch = new CountDownLatch(1);
    Session<?> session = sessionFactory.getSession();
    session.close();
    session = TestUtils.getPropertyValue(session, "targetSession", Session.class);
    SftpClient sftpClient = spy(TestUtils.getPropertyValue(session, "sftpClient", SftpClient.class));
    doNothing().when(sftpClient).setStat(anyString(), any(SftpClient.Attributes.class));
    new DirectFieldAccessor(session).setPropertyValue("sftpClient", sftpClient);
    String dir = "sftpSource/";
    this.inboundMGetRecursive.send(new GenericMessage<Object>(dir + "*"));
    while (output.receive(0) != null) {
        // drain
    }
    this.inboundMPut.send(new GenericMessage<>(getSourceLocalDirectory()));
    @SuppressWarnings("unchecked")
    Message<List<String>> out = (Message<List<String>>) this.output.receive(1000);
    assertThat(out).isNotNull();
    assertThat(out.getPayload()).hasSize(2);
    assertThat(out.getPayload().get(0)).isNotEqualTo(out.getPayload().get(1));
    assertThat(out.getPayload().get(0)).isIn("sftpTarget/localSource1.txt", "sftpTarget/localSource2.txt");
    assertThat(out.getPayload().get(1)).isIn("sftpTarget/localSource1.txt", "sftpTarget/localSource2.txt");
    verify(sftpClient).setStat(eq("sftpTarget/localSource1.txt"), any(SftpClient.Attributes.class));
    verify(sftpClient).setStat(eq("sftpTarget/localSource2.txt"), any(SftpClient.Attributes.class));
    resetSessionCache();
    assertThat(this.config.latch.await(10, TimeUnit.SECONDS)).isTrue();
    assertThat(this.config.events).hasSize(6);
    assertThat(this.config.events.get(0)).isInstanceOf(SessionOpenedEvent.class);
    assertThat(this.config.events.get(1)).isInstanceOf(FileWrittenEvent.class);
    assertThat(((FileWrittenEvent) this.config.events.get(1)).getFile().toString()).matches("/sftpTarget/localSource(1|2).txt.writing");
    assertThat(this.config.events.get(2)).isInstanceOf(PathMovedEvent.class);
    assertThat(((PathMovedEvent) this.config.events.get(2)).getSrcPath().toString()).matches("/sftpTarget/localSource(1|2).txt.writing");
    assertThat(((PathMovedEvent) this.config.events.get(2)).getDstPath().toString()).matches("/sftpTarget/localSource(1|2).txt");
    assertThat(this.config.events.get(3)).isInstanceOf(FileWrittenEvent.class);
    assertThat(((FileWrittenEvent) this.config.events.get(3)).getFile().toString()).matches("/sftpTarget/localSource(1|2).txt.writing");
    assertThat(this.config.events.get(4)).isInstanceOf(PathMovedEvent.class);
    assertThat(((PathMovedEvent) this.config.events.get(4)).getSrcPath().toString()).matches("/sftpTarget/localSource(1|2).txt.writing");
    assertThat(((PathMovedEvent) this.config.events.get(4)).getDstPath().toString()).matches("/sftpTarget/localSource(1|2).txt");
    assertThat(this.config.events.get(5)).isInstanceOf(SessionClosedEvent.class);
    this.config.events.clear();
    this.config.latch = null;
}

