@Test
public void testStream() {
    Session<?> session = spy(this.sessionFactory.getSession());
    session.close();
    String dir = "sftpSource/";
    this.inboundGetStream.send(new GenericMessage<>(dir + " sftpSource1.txt"));
    Message<?> result = this.output.receive(1000);
    assertThat(result).isNotNull();
    assertThat(result.getPayload()).isEqualTo("source1");
    assertThat(result.getHeaders()).containsEntry(FileHeaders.REMOTE_DIRECTORY, "sftpSource/").containsEntry(FileHeaders.REMOTE_FILE, " sftpSource1.txt");
    verify(session).close();
    assertThatExceptionOfType(MessageHandlingException.class).isThrownBy(() -> this.inboundGetStream.send(new GenericMessage<>(dir + "doesNotExist.txt"))).withStackTraceContaining("No such file or directory");
    // No leak for not closed session after the previous failure
    assertThatExceptionOfType(MessageHandlingException.class).isThrownBy(() -> this.inboundGetStream.send(new GenericMessage<>(dir + "doesNotExist.txt"))).withStackTraceContaining("No such file or directory");
}

