public void testMockRawHandler() {
    ArgumentCaptor<Message<?>> messageArgumentCaptor = MockIntegration.messageArgumentCaptor();
    MessageHandler mockMessageHandler = mockMessageHandler(messageArgumentCaptor).handleNext(m -> {
    });
    String endpointId = "rawHandlerConsumer";
    this.mockIntegrationContext.substituteMessageHandlerFor(endpointId, mockMessageHandler);
    Object endpoint = this.context.getBean(endpointId);
    assertThat(TestUtils.getPropertyValue(endpoint, "handler", MessageHandler.class)).isSameAs(mockMessageHandler);
    GenericMessage<String> message = new GenericMessage<>("foo");
    this.rawChannel.send(message);
    verify(mockMessageHandler).handleMessage(message);
    assertThat(messageArgumentCaptor.getValue()).isSameAs(message);
    this.mockIntegrationContext.resetBeans(endpointId);
    MessageHandler mockMessageHandler2 = mockMessageHandler().handleNextAndReply(m -> m);
    assertThatIllegalStateException().isThrownBy(() -> this.mockIntegrationContext.substituteMessageHandlerFor(endpointId, mockMessageHandler2)).withMessageContaining("with replies can't replace simple MessageHandler");
    this.mockIntegrationContext.resetBeans();
    assertThat(TestUtils.getPropertyValue(endpoint, "handler", MessageHandler.class)).isNotSameAs(mockMessageHandler2);
    assertThat(TestUtils.getPropertyValue(endpoint, "subscriber", Subscriber.class)).isNotSameAs(mockMessageHandler2);
}

