@Test
void testDynamicServerEndpointRegistration() throws Exception {
    // Dynamic server flow
    AnnotationConfigWebApplicationContext serverContext = this.server.getServerContext();
    IntegrationFlowContext serverIntegrationFlowContext = serverContext.getBean(IntegrationFlowContext.class);
    AtomicReference<WebSocketHandler> decoratedHandler = new AtomicReference<>();
    ServerWebSocketContainer serverWebSocketContainer = new ServerWebSocketContainer("/dynamic").setHandshakeHandler(serverContext.getBean(HandshakeHandler.class)).setDecoratorFactories(handler -> {
        WebSocketHandler spy = spy(handler);
        decoratedHandler.set(spy);
        return spy;
    }).withSockJs();
    WebSocketInboundChannelAdapter webSocketInboundChannelAdapter = new WebSocketInboundChannelAdapter(serverWebSocketContainer);
    QueueChannel dynamicRequestsChannel = new QueueChannel();
    IntegrationFlow serverFlow = IntegrationFlow.from(webSocketInboundChannelAdapter).channel(dynamicRequestsChannel).get();
    IntegrationFlowContext.IntegrationFlowRegistration dynamicServerFlow = serverIntegrationFlowContext.registration(serverFlow).addBean(serverWebSocketContainer).register();
    // Dynamic client flow
    ClientWebSocketContainer clientWebSocketContainer = new ClientWebSocketContainer(this.webSocketClient, this.server.getWsBaseUrl() + "/dynamic/websocket");
    clientWebSocketContainer.setAutoStartup(true);
    WebSocketOutboundMessageHandler webSocketOutboundMessageHandler = new WebSocketOutboundMessageHandler(clientWebSocketContainer);
    IntegrationFlow clientFlow = flow -> flow.handle(webSocketOutboundMessageHandler);
    IntegrationFlowContext.IntegrationFlowRegistration dynamicClientFlow = this.integrationFlowContext.registration(clientFlow).addBean(clientWebSocketContainer).register();
    dynamicClientFlow.getInputChannel().send(new GenericMessage<>("dynamic test"));
    Message<?> result = dynamicRequestsChannel.receive(10_000);
    assertThat(result).isNotNull().extracting(Message::getPayload).isEqualTo("dynamic test");
    verify(decoratedHandler.get()).handleMessage(any(), any());
    dynamicServerFlow.destroy();
    // Looks like endpoint is removed on the server side somewhat async
    await().untilAsserted(() -> assertThatExceptionOfType(MessageHandlingException.class).isThrownBy(() -> dynamicClientFlow.getInputChannel().send(new GenericMessage<>("another test"))).withCauseInstanceOf(DeploymentException.class).withStackTraceContaining("The HTTP response from the server [404]"));
    dynamicClientFlow.destroy();
}

